    public class ClientSession : IDisposable
    {
        public TcpClient Client { get; }
        public NetworkStream Stream { get; }
        public string DeviceId { get; set; } = string.Empty;
        public DateTime ConnectedAt { get; } = DateTime.UtcNow;
        public DateTime LastActivity { get; set; } = DateTime.UtcNow;
        public bool IsAuthenticated { get; set; } = false;
    
        public ClientSession(TcpClient client)
        {
            Client = client;
            Stream = client.GetStream();
        }
    
        public async Task SendAsync(NetworkMessage message, CancellationToken cancellationToken = default)
        {
            var json = message.ToJson();
            message.Checksum = SecurityHelper.CalculateMD5(json);
            var encrypted = SecurityHelper.Encrypt(json);
            var compressed = SecurityHelper.CompressString(encrypted);
            var data = Encoding.UTF8.GetBytes(compressed);
    
            var lengthPrefix = BitConverter.GetBytes(data.Length);
            await Stream.WriteAsync(lengthPrefix.AsMemory(0, 4), cancellationToken);
            await Stream.WriteAsync(data.AsMemory(0, data.Length), cancellationToken);
            await Stream.FlushAsync(cancellationToken);
        }
    
        public void Dispose()
        {
            Stream?.Close();
            Client?.Close();
        }
    }
