    public class ServerEngine : IDisposable
    {
        private TcpListener? _listener;
        private CancellationTokenSource? _cts;
        private Task? _listenerTask;
        private Task[]? _workerTasks;
        private readonly ConcurrentDictionary<string, ClientSession> _clients = new();
        private readonly ConcurrentQueue<NetworkMessage> _messageQueue = new();
        private readonly int _port;
        private readonly int _workerCount;
        private readonly AppSettings _settings;
    
        public bool IsRunning { get; private set; }
        public IReadOnlyDictionary<string, ClientSession> ConnectedClients => _clients;
        public int QueueSize => _messageQueue.Count;
        public int ConnectedCount => _clients.Count;
    
        public event EventHandler<NetworkMessage>? MessageReceived;
        public event EventHandler<string>? ClientConnected;
        public event EventHandler<string>? ClientDisconnected;
        public event EventHandler<AlertPayload>? AlertGenerated;
    
        public ServerEngine(AppSettings settings)
        {
            _settings = settings;
            _port = settings.ServerPort;
            _workerCount = settings.WorkerThreadCount;
        }
    
        public async Task StartAsync(CancellationToken cancellationToken = default)
        {
            _cts = new CancellationTokenSource();
            var combinedToken = CancellationTokenSource.CreateLinkedTokenSource(_cts.Token, cancellationToken).Token;
    
            _listener = new TcpListener(IPAddress.Any, _port);
            _listener.Start();
            IsRunning = true;
    
            Logger.Info($"Server started on port {_port}", "ServerEngine");
    
            // Start worker threads
            _workerTasks = new Task[_workerCount];
            for (int i = 0; i < _workerCount; i++)
            {
                int workerId = i;
                _workerTasks[i] = Task.Run(() => WorkerLoopAsync(workerId, combinedToken), combinedToken);
            }
    
            // Start listener
            _listenerTask = Task.Run(() => ListenerLoopAsync(combinedToken), combinedToken);
        }
    
        public async Task StopAsync()
        {
            _cts?.Cancel();
            IsRunning = false;
            _listener?.Stop();
    
            if (_listenerTask != null)
                try { await _listenerTask.WaitAsync(TimeSpan.FromSeconds(5)); } catch { }
    
            if (_workerTasks != null)
                await Task.WhenAll(_workerTasks.Select(t =>
                    t.WaitAsync(TimeSpan.FromSeconds(5)).ContinueWith(_ => { })));
    
            foreach (var client in _clients.Values)
                client.Dispose();
            _clients.Clear();
    
            Logger.Info("Server stopped", "ServerEngine");
        }
    
        public async Task BroadcastAsync(NetworkMessage message, CancellationToken cancellationToken = default)
        {
            var tasks = _clients.Values.Select(c => c.SendAsync(message, cancellationToken));
            await Task.WhenAll(tasks);
        }
    
        public async Task SendToClientAsync(string deviceId, NetworkMessage message,
                                            CancellationToken cancellationToken = default)
        {
            if (_clients.TryGetValue(deviceId, out var client))
            {
                await client.SendAsync(message, cancellationToken);
            }
        }
    
        private async Task ListenerLoopAsync(CancellationToken cancellationToken)
        {
            while (!cancellationToken.IsCancellationRequested && IsRunning)
            {
                try
                {
                    var tcpClient = await _listener!.AcceptTcpClientAsync(cancellationToken);
                    var endpoint = tcpClient.Client.RemoteEndPoint?.ToString() ?? "unknown";
    
                    _ = Task.Run(async () =>
                    {
                        try
                        {
                            await HandleClientAsync(tcpClient, cancellationToken);
                        }
                        catch (Exception ex)
                        {
                            Logger.Warning($"Client handler error: {ex.Message}", "ServerEngine");
                        }
                    }, cancellationToken);
                }
                catch (OperationCanceledException)
                {
                    break;
                }
                catch (Exception ex)
                {
                    Logger.Error($"Listener error: {ex.Message}", "ServerEngine");
                    await Task.Delay(1000, cancellationToken);
                }
            }
        }
    
        private async Task HandleClientAsync(TcpClient tcpClient, CancellationToken cancellationToken)
        {
            var session = new ClientSession(tcpClient);
            var endpoint = tcpClient.Client.RemoteEndPoint?.ToString() ?? "unknown";
    
            try
            {
                var buffer = new byte[8192];
    
                while (!cancellationToken.IsCancellationRequested && tcpClient.Connected)
                {
                    // Read length prefix
                    var lengthBytes = new byte[4];
                    var read = await session.Stream.ReadAsync(lengthBytes.AsMemory(0, 4), cancellationToken);
                    if (read < 4) break;
    
                    var messageLength = BitConverter.ToInt32(lengthBytes, 0);
                    if (messageLength <= 0 || messageLength > 10 * 1024 * 1024) continue;
    
                    // Read message
                    var messageBytes = new byte[messageLength];
                    var totalRead = 0;
                    while (totalRead < messageLength)
                    {
                        var chunk = await session.Stream.ReadAsync(
                            messageBytes.AsMemory(totalRead, messageLength - totalRead), cancellationToken);
                        if (chunk == 0) break;
                        totalRead += chunk;
                    }
    
                    if (totalRead < messageLength) break;
    
                    // Decrypt and parse
                    var compressed = Encoding.UTF8.GetString(messageBytes);
                    var encrypted = SecurityHelper.DecompressString(compressed);
                    var json = SecurityHelper.Decrypt(encrypted);
                    var message = NetworkMessage.FromJson(json);
    
                    if (message != null)
                    {
                        // Update client registry
                        if (!string.IsNullOrEmpty(message.DeviceId))
                        {
                            session.DeviceId = message.DeviceId;
                            session.LastActivity = DateTime.UtcNow;
                            _clients.AddOrUpdate(message.DeviceId, session, (_, __) => session);
    
                            if (message.Command == CommandType.Heartbeat)
                            {
                                ClientConnected?.Invoke(this, message.DeviceId);
                            }
                        }
    
                        // Enqueue for processing
                        _messageQueue.Enqueue(message);
                    }
                }
            }
            catch (OperationCanceledException) { }
            catch (Exception ex)
            {
                Logger.Warning($"Client {endpoint} error: {ex.Message}", "ServerEngine");
            }
            finally
            {
                if (!string.IsNullOrEmpty(session.DeviceId))
                {
                    _clients.TryRemove(session.DeviceId, out _);
                    ClientDisconnected?.Invoke(this, session.DeviceId);
    
                    // Generate offline alert
                    AlertGenerated?.Invoke(this, new AlertPayload
                    {
                        Severity = AlertSeverity.Warning,
                        Title = "Device Disconnected",
                        Message = $"ATM {session.DeviceId} disconnected unexpectedly",
                        Source = session.DeviceId
                    });
                }
                session.Dispose();
            }
        }
    
        private async Task WorkerLoopAsync(int workerId, CancellationToken cancellationToken)
        {
            Logger.Info($"Worker {workerId} started", "ServerEngine");
    
            while (!cancellationToken.IsCancellationRequested && IsRunning)
            {
                if (_messageQueue.TryDequeue(out var message))
                {
                    try
                    {
                        MessageReceived?.Invoke(this, message);
                    }
                    catch (Exception ex)
                    {
                        Logger.Error($"Worker {workerId} processing error: {ex.Message}", "ServerEngine");
                    }
                }
                else
                {
                    await Task.Delay(10, cancellationToken);
                }
            }
        }
    
        public void Dispose()
        {
            _ = StopAsync();
            _cts?.Dispose();
        }
    }
