            }
            private void ClientReceiveLoop(ClientConnection conn, string atmFolder)
            {
                byte[] buffer = new byte[NetworkConfig.SOCKET_BUFFER_SIZE];
                StringBuilder msgBuilder = new StringBuilder();
                while (_isRunning && conn.IsConnected)
                {
                try
                {
                    if (!conn.Stream.DataAvailable)
                    {
                    Thread.Sleep(50);
                    // فحص Heartbeat timeout
                    if ((DateTime.Now - conn.ATMData.LastHeartbeat).TotalSeconds > 90)
                    {
                        OnLog?.Invoke("[Server] Heartbeat timeout: " + conn.ATMData.ATM_ID);
                        break;
                    }
                    continue;
                    }
                    int bytesRead = conn.Stream.Read(buffer, 0, buffer.Length);
                    if (bytesRead == 0) break;
                    string received = Encoding.UTF8.GetString(buffer, 0, bytesRead);
                    msgBuilder.Append(received);
                    string full = msgBuilder.ToString();
                    int idx;
                    while ((idx = full.IndexOf('\n')) >= 0)
                    {
                    string line = full.Substring(0, idx).Trim();
                    full = full.Substring(idx + 1);
                    if (!string.IsNullOrEmpty(line))
                    {
                        ProcessClientMessage(conn, line, atmFolder);
                    }
                    }
                    msgBuilder.Clear();
                    if (full.Length > 0) msgBuilder.Append(full);
                }
                catch (Exception)
                {
                    break;
                }
                }
            }
            private void ProcessClientMessage(ClientConnection conn, string message, string atmFolder)
            {
                string[] parts = Protocol.ParseMessage(message);
                if (parts.Length == 0) return;
                string msgType = parts[0];
                string atmId = conn.ATMData.ATM_ID;
                switch (msgType)
                {
                case Protocol.HEARTBEAT:
                    conn.ATMData.LastHeartbeat = DateTime.Now;
                    conn.ATMData.IsConnected = true;
                    // رد Heartbeat
                    conn.Send(Protocol.HEARTBEAT_ACK);
                    break;
                case Protocol.DATA_JOURNAL:
                    // EJDATA|ATM_ID|FILENAME|LENGTH|CHECKSUM|TIMESTAMP
                    if (parts.Length >= 5)
                    {
                    string fileName = parts[2];
                    int dataLength = int.Parse(parts[3]);
                    // البيانات ستأتي في الرسائل التالية
                    conn.ATMData.IsSendingData = true;
                    conn.ATMData.LastDataReceived = DateTime.Now;
                    conn.ATMData.Status = ATMStatus.Online_Active;
                    conn.ATMData.TotalLinesSent++;
                    // حفظ البيانات
                    OnDataReceived?.Invoke(atmId, fileName, null);
                    conn.Send(Protocol.DATA_ACK);
                    }
                    break;
                case Protocol.DATA_FILE:
                    if (parts.Length >= 5)
                    {
                    string fileName = parts[2];
                    conn.ATMData.IsSendingData = true;
                    conn.ATMData.LastDataReceived = DateTime.Now;
                    conn.ATMData.TotalFilesSynced++;
                    OnFileReceived?.Invoke(atmId, fileName, null);
                    conn.Send(Protocol.DATA_ACK);
                    }
                    break;
                case Protocol.STATUS_RESPONSE:
                    if (parts.Length >= 4)
                    {
                    string status = parts[2];
                    string cscStatus = parts.Length > 3 ? parts[3] : "";
                    conn.ATMData.IsCSCConnected = (cscStatus == "CSC_OK");
                    OnStatusReceived?.Invoke(atmId, status);
                    }
                    break;
                case Protocol.CMD_RESULT:
                    if (parts.Length >= 4)
                    {
                    string cmdId = parts[2];
                    string result = parts[3];
                    OnCommandResult?.Invoke(atmId, cmdId, result);
                    }
                    break;
                }
            }
            private string ReadLine(NetworkStream stream, int timeoutMs)
            {
                byte[] buffer = new byte[4096];
                stream.ReadTimeout = timeoutMs;
                try
                {
                int bytesRead = stream.Read(buffer, 0, buffer.Length);
                if (bytesRead > 0)
                    return Encoding.UTF8.GetString(buffer, 0, bytesRead).Trim();
                }
                catch { }
                return null;
            }
            #endregion
            }
            public class ClientConnection
            {
            public TcpClient Client { get; private set; }
            public NetworkStream Stream { get; private set; }
            public ATMInfo ATMData { get; set; }
            public bool IsConnected { get; private set; }
            private readonly object _sendLock = new object();
            public ClientConnection(TcpClient client, NetworkStream stream, ATMInfo atmData)
            {
                Client = client;
                Stream = stream;
                ATMData = atmData;
                IsConnected = true;
            }
            public bool Send(string message)
            {
                try
                {
                if (!IsConnected) return false;
                lock (_sendLock)
                {
                    byte[] data = Encoding.UTF8.GetBytes(message + "\n");
                    Stream.Write(data, 0, data.Length);
                    Stream.Flush();
                }
                return true;
                }
                catch { IsConnected = false; return false; }
            }
            public void Disconnect()
            {
                IsConnected = false;
                try { Stream?.Close(); } catch { }
                try { Client?.Close(); } catch { }
            }
            }
        }
        /// <summary>
        /// Server engine for handling client connections and communication
        /// </summary>
        public class ServerEngine
        {
            public bool IsRunning { get; private set; } = false;
            public int Port { get; set; } = 8080;
            public string Host { get; set; } = "localhost";
            public DateTime StartTime { get; private set; }
    
            private TcpListener _listener;
            private readonly List<ConnectedClient> _clients = new List<ConnectedClient>();
            private readonly object _lockObject = new object();
            private bool _isProcessing = false;
            private string _archivePath;
    
            // Events
            public event Action<string> OnLog;
            public event Action<Exception> OnError;
            public event Action<string, string, string> OnClientConnected; // atmId, atmType, ip
            public event Action<string> OnClientDisconnected; // atmId
            public event Action<string, string, long> OnJournalReceived; // atmId, fileName, size
            public event Action<string, string, bool, string> OnCommandResult; // atmId, command, success, result
    
            public ServerEngine(int port, string archivePath)
            {
            Port = port;
            _archivePath = archivePath;
            StartTime = DateTime.Now;
            }
    
            public void Start()
            {
            try
            {
                _listener = new TcpListener(IPAddress.Any, Port);
                _listener.Start();
                IsRunning = true;
                StartTime = DateTime.Now;
    
                // Start listening for connections
                Task.Run(() => AcceptClients());
    
                OnLog?.Invoke($"[Server] Started on port {Port}");
            }
            catch (Exception ex)
            {
                OnError?.Invoke(ex);
            }
            }
    
            public void Stop()
            {
            try
            {
                _isProcessing = false;
                _listener?.Stop();
                IsRunning = false;
    
                // Disconnect all clients
                lock (_lockObject)
                {
                foreach (var client in _clients)
                {
                    client.TcpClient?.Close();
                }
                _clients.Clear();
                }
    
                OnLog?.Invoke("[Server] Stopped");
            }
            catch (Exception ex)
            {
                OnError?.Invoke(ex);
            }
            }
    
            private async Task AcceptClients()
            {
            _isProcessing = true;
            OnLog?.Invoke("[Server] Listening for connections...");
    
            while (_isProcessing && IsRunning)
            {
                try
                {
                var tcpClient = await _listener.AcceptTcpClientAsync();
                var client = new ConnectedClient
                {
                    TcpClient = tcpClient,
                    IP = ((IPEndPoint)tcpClient.Client.RemoteEndPoint).Address.ToString(),
                    ConnectedAt = DateTime.Now
                };
    
                lock (_lockObject)
                {
                    _clients.Add(client);
                }
    
                OnLog?.Invoke($"[Server] Client connected from {client.IP}");
    
                // Start processing this client
                Task.Run(() => ProcessClient(client));
                }
                catch (ObjectDisposedException)
                {
                // Server stopped
                break;
                }
                catch (Exception ex)
                {
                if (_isProcessing)
                {
                    OnError?.Invoke(ex);
                }
                }
            }
            }
    
            private async void ProcessClient(ConnectedClient client)
            {
            try
            {
                var stream = client.TcpClient.GetStream();
                var buffer = new byte[4096];
                var atmId = "Unknown";
    
                while (IsRunning && client.TcpClient.Connected)
                {
                // Read data from client
                int bytesRead = await stream.ReadAsync(buffer, 0, buffer.Length);
                if (bytesRead == 0)
                {
                    // Client disconnected
                    break;
                }
    
                var data = Encoding.UTF8.GetString(buffer, 0, bytesRead);
                ProcessClientMessage(client, data, ref atmId);
                }
            }
            catch (Exception ex)
            {
                OnError?.Invoke(ex);
            }
            finally
            {
                // Client disconnected
                HandleClientDisconnection(client, atmId);
            }
            }
    
            private void ProcessClientMessage(ConnectedClient client, string data, ref string atmId)
            {
            try
            {
                // Parse the message
                var parts = data.Split('|');
                if (parts.Length > 0)
                {
                switch (parts[0])
                {
                    case "EJLIVE_HANDSHAKE":
                    if (parts.Length >= 3)
                    {
                        atmId = parts[1];
                        var atmType = parts[2];
                        client.ATMId = atmId;
                        client.ATMType = atmType;
                        OnClientConnected?.Invoke(atmId, atmType, client.IP);
    
                        // Send handshake acknowledgment
                        SendDataToClient(client, "EJLIVE_ACK");
                    }
                    break;
    
                    case "EJDATA":
                    if (parts.Length >= 3)
                    {
                        var fileName = parts[1];
                        var fileData = parts[2];
    
                        // Save the journal file
                        SaveJournalFile(client.ATMId, fileName, fileData);
                        OnJournalReceived?.Invoke(client.ATMId, fileName, fileData.Length);
                    }
                    break;
    
                    case "CMD_RESULT":
                    if (parts.Length >= 4)
                    {
                        var command = parts[1];
                        var success = parts[2] == "SUCCESS";
                        var result = parts[3];
                        OnCommandResult?.Invoke(client.ATMId, command, success, result);
                    }
                    break;
                }
                }
            }
            catch (Exception ex)
            {
                OnError?.Invoke(ex);
            }
            }
    
            private void HandleClientDisconnection(ConnectedClient client, string atmId)
            {
            try
            {
                lock (_lockObject)
                {
                _clients.Remove(client);
                }
    
                if (client.TcpClient != null)
                {
                client.TcpClient.Close();
                }
    
                if (!string.IsNullOrEmpty(atmId) && atmId != "Unknown")
                {
                OnClientDisconnected?.Invoke(atmId);
                }
    
                OnLog?.Invoke($"[Server] Client {atmId} disconnected");
            }
            catch (Exception ex)
            {
                OnError?.Invoke(ex);
            }
            }
    
            private void SaveJournalFile(string atmId, string fileName, string fileData)
            {
            try
            {
                var atmPath = Path.Combine(_archivePath, atmId);
                if (!Directory.Exists(atmPath))
                {
                Directory.CreateDirectory(atmPath);
                }
    
                var filePath = Path.Combine(atmPath, fileName);
                File.WriteAllText(filePath, fileData);
            }
            catch (Exception ex)
            {
                OnError?.Invoke(ex);
            }
            }
    
            public void SendCommand(string atmId, string command, string[] parameters)
            {
            lock (_lockObject)
            {
                var client = _clients.Find(c => c.ATMId == atmId);
                if (client != null)
                {
                var message = Protocol.BuildMessage(command, parameters);
                SendDataToClient(client, message);
                }
            }
            }
    
            public void BroadcastCommand(string command, string[] parameters)
            {
            lock (_lockObject)
            {
                var message = Protocol.BuildMessage(command, parameters);
                foreach (var client in _clients)
                {
                SendDataToClient(client, message);
                }
            }
            }
    
            public void DisconnectClient(string atmId)
            {
            lock (_lockObject)
            {
                var client = _clients.Find(c => c.ATMId == atmId);
                if (client != null)
                {
                client.TcpClient?.Close();
                }
            }
            }
    
            private void SendDataToClient(ConnectedClient client, string data)
            {
            try
            {
                if (client.TcpClient?.Connected == true)
                {
                var bytes = Encoding.UTF8.GetBytes(data);
                var stream = client.TcpClient.GetStream();
                stream.Write(bytes, 0, bytes.Length);
                }
            }
            catch (Exception ex)
            {
                OnError?.Invoke(ex);
            }
            }
    
            public bool SendDataToAll(string data)
            {
            lock (_lockObject)
            {
                try
                {
                foreach (var client in _clients)
                {
                    SendDataToClient(client, data);
                }
                return true;
                }
                catch (Exception ex)
                {
                OnError?.Invoke(ex);
                return false;
                }
            }
            }
    
            public bool SendData(string data, TcpClient tcpClient)
            {
            try
            {
                if (tcpClient?.Connected == true)
                {
                var bytes = Encoding.UTF8.GetBytes(data);
                var stream = tcpClient.GetStream();
                stream.Write(bytes, 0, bytes.Length);
                return true;
                }
                return false;
            }
            catch (Exception ex)
            {
                OnError?.Invoke(ex);
                return false;
            }
            }
    
            private class ConnectedClient
            {
            public TcpClient TcpClient { get; set; }
            public string IP { get; set; }
            public string ATMId { get; set; }
            public string ATMType { get; set; }
            public DateTime ConnectedAt { get; set; }
            }
        }
        /// <summary>
        /// محرك السيرفر - يستقبل اتصالات الكلاينتات ويدير البيانات الواردة
        /// </summary>
        public class ServerEngine
        {
            private TcpListener _listener;
            private Thread _listenThread;
            private bool _isRunning;
            private int _port;
            private string _storagePath;
            private Dictionary<string, ClientConnection> _connections;
            private readonly object _connectionsLock = new object();
    
            // أحداث
            public event Action<string, ATMInfo> OnClientConnected;
            public event Action<string> OnClientDisconnected;
            public event Action<string, string, byte[]> OnDataReceived;  // (atmId, fileName, data)
            public event Action<string, string, byte[]> OnFileReceived;  // (atmId, fileName, data)
            public event Action<string, string> OnStatusReceived;        // (atmId, status)
            public event Action<string, string, string> OnCommandResult; // (atmId, cmdId, result)
            public event Action<string> OnLog;
            public event Action<Exception> OnError;
    
            public bool IsRunning { get { return _isRunning; } }
            public int ConnectedClients { get { lock (_connectionsLock) return _connections.Count; } }
    
            public ServerEngine(int port, string storagePath)
            {
            _port = port;
            _storagePath = storagePath;
            _connections = new Dictionary<string, ClientConnection>();
            }
    
            /// <summary>
            /// بدء السيرفر
            /// </summary>
            public bool Start()
            {
            try
            {
                if (_isRunning) return true;
    
                if (!Directory.Exists(_storagePath))
                Directory.CreateDirectory(_storagePath);
    
                _listener = new TcpListener(IPAddress.Any, _port);
                _listener.Start();
                _isRunning = true;
    
                _listenThread = new Thread(ListenLoop);
                _listenThread.IsBackground = true;
                _listenThread.Start();
    
                OnLog?.Invoke("[Server] Started on port " + _port);
                return true;
            }
            catch (Exception ex)
            {
                OnError?.Invoke(ex);
                return false;
            }
            }
    
            /// <summary>
            /// إيقاف السيرفر
            /// </summary>
            public void Stop()
            {
            _isRunning = false;
            try
            {
                _listener?.Stop();
                lock (_connectionsLock)
                {
                foreach (var conn in _connections.Values)
                    conn.Disconnect();
                _connections.Clear();
                }
            }
            catch { }
            OnLog?.Invoke("[Server] Stopped");
            }
    
            /// <summary>
            /// إرسال أمر إلى صراف محدد
            /// </summary>
            public bool SendCommand(string atmId, string command, string[] parameters)
            {
            lock (_connectionsLock)
            {
                if (!_connections.ContainsKey(atmId)) return false;
                var conn = _connections[atmId];
                string msg = Protocol.BuildMessage(command, parameters);
                return conn.Send(msg);
            }
            }
    
            /// <summary>
            /// إرسال أمر لجميع الصرافات المتصلة
            /// </summary>
            public int BroadcastCommand(string command, string[] parameters)
            {
            int sent = 0;
            lock (_connectionsLock)
            {
                foreach (var conn in _connections.Values)
                {
                string msg = Protocol.BuildMessage(command, parameters);
                if (conn.Send(msg)) sent++;
                }
            }
            return sent;
            }
    
            /// <summary>
            /// الحصول على قائمة الصرافات المتصلة
            /// </summary>
            public List<ATMInfo> GetConnectedATMs()
            {
            var list = new List<ATMInfo>();
            lock (_connectionsLock)
            {
                foreach (var conn in _connections.Values)
                list.Add(conn.ATMData);
            }
            return list;
            }
    
            /// <summary>
            /// طلب حالة صراف محدد
            /// </summary>
            public bool RequestStatus(string atmId)
            {
            return SendCommand(atmId, Protocol.STATUS_REQUEST, new string[] { });
            }
    
            #region Private Methods
    
            private void ListenLoop()
            {
            while (_isRunning)
            {
                try
                {
                if (_listener.Pending())
                {
                    TcpClient client = _listener.AcceptTcpClient();
                    Thread clientThread = new Thread(() => HandleClient(client));
                    clientThread.IsBackground = true;
                    clientThread.Start();
                }
                else
                {
                    Thread.Sleep(100);
                }
                }
                catch (Exception ex)
                {
                if (_isRunning) OnError?.Invoke(ex);
                }
            }
            }
    
            private void HandleClient(TcpClient tcpClient)
            {
            string atmId = null;
            try
            {
                var stream = tcpClient.GetStream();
                stream.ReadTimeout = NetworkConfig.CONNECTION_TIMEOUT_MS;
    
                // انتظار Handshake
                string handshake = ReadLine(stream, 10000);
                if (string.IsNullOrEmpty(handshake))
                {
                tcpClient.Close();
                return;
                }
    
                string[] parts = Protocol.ParseMessage(handshake);
                if (parts.Length < 4 || parts[0] != Protocol.HANDSHAKE)
                {
                // رفض الاتصال
                byte[] reject = Encoding.UTF8.GetBytes(Protocol.HANDSHAKE_REJECT + "\n");
                stream.Write(reject, 0, reject.Length);
                tcpClient.Close();
                return;
                }
    
                atmId = parts[1];
                string atmType = parts[2];
                string version = parts[3];
    
                // قبول الاتصال
                byte[] ack = Encoding.UTF8.GetBytes(Protocol.HANDSHAKE_ACK + "\n");
                stream.Write(ack, 0, ack.Length);
    
                // إنشاء اتصال جديد
                var atmInfo = new ATMInfo
                {
                ATM_ID = atmId,
                ATM_Type = atmType,
                ClientVersion = version,
                IsConnected = true,
                LastConnectionTime = DateTime.Now,
                LastHeartbeat = DateTime.Now,
                Status = ATMStatus.Online_Active
                };
    
                var connection = new ClientConnection(tcpClient, stream, atmInfo);
    
                lock (_connectionsLock)
                {
                if (_connections.ContainsKey(atmId))
                {
                    _connections[atmId].Disconnect();
                    _connections.Remove(atmId);
                }
                _connections[atmId] = connection;
                }
    
                // إنشاء مجلد للصراف في التخزين
                string atmFolder = Path.Combine(_storagePath, atmId);
                if (!Directory.Exists(atmFolder))
                Directory.CreateDirectory(atmFolder);
    
                OnLog?.Invoke("[Server] Client connected: " + atmId + " (" + atmType + ")");
                OnClientConnected?.Invoke(atmId, atmInfo);
    
                // حلقة الاستقبال
                ClientReceiveLoop(connection, atmFolder);
            }
            catch (Exception ex)
            {
                OnError?.Invoke(ex);
            }
            finally
            {
                if (atmId != null)
                {
                lock (_connectionsLock)
                {
                    if (_connections.ContainsKey(atmId))
                    {
                    _connections[atmId].ATMData.IsConnected = false;
                    _connections[atmId].ATMData.Status = ATMStatus.Offline;
                    _connections.Remove(atmId);
                    }
                }
                OnClientDisconnected?.Invoke(atmId);
                OnLog?.Invoke("[Server] Client disconnected: " + atmId);
                }
                try { tcpClient.Close(); } catch { }
            }
            }
    
            private void ClientReceiveLoop(ClientConnection conn, string atmFolder)
            {
            byte[] buffer = new byte[NetworkConfig.SOCKET_BUFFER_SIZE];
            StringBuilder msgBuilder = new StringBuilder();
    
            while (_isRunning && conn.IsConnected)
            {
                try
                {
                if (!conn.Stream.DataAvailable)
                {
                    Thread.Sleep(50);
                    // فحص Heartbeat timeout
                    if ((DateTime.Now - conn.ATMData.LastHeartbeat).TotalSeconds > 90)
                    {
                    OnLog?.Invoke("[Server] Heartbeat timeout: " + conn.ATMData.ATM_ID);
                    break;
                    }
                    continue;
                }
    
                int bytesRead = conn.Stream.Read(buffer, 0, buffer.Length);
                if (bytesRead == 0) break;
    
                string received = Encoding.UTF8.GetString(buffer, 0, bytesRead);
                msgBuilder.Append(received);
    
                string full = msgBuilder.ToString();
                int idx;
                while ((idx = full.IndexOf('\n')) >= 0)
                {
                    string line = full.Substring(0, idx).Trim();
                    full = full.Substring(idx + 1);
    
                    if (!string.IsNullOrEmpty(line))
                    {
                    ProcessClientMessage(conn, line, atmFolder);
                    }
                }
                msgBuilder.Clear();
                if (full.Length > 0) msgBuilder.Append(full);
                }
                catch (Exception)
                {
                break;
                }
            }
            }
    
            private void ProcessClientMessage(ClientConnection conn, string message, string atmFolder)
            {
            string[] parts = Protocol.ParseMessage(message);
            if (parts.Length == 0) return;
    
            string msgType = parts[0];
            string atmId = conn.ATMData.ATM_ID;
    
            switch (msgType)
            {
                case Protocol.HEARTBEAT:
                conn.ATMData.LastHeartbeat = DateTime.Now;
                conn.ATMData.IsConnected = true;
                // رد Heartbeat
                conn.Send(Protocol.HEARTBEAT_ACK);
                break;
    
                case Protocol.DATA_JOURNAL:
                // EJDATA|ATM_ID|FILENAME|LENGTH|CHECKSUM|TIMESTAMP
                if (parts.Length >= 5)
                {
                    string fileName = parts[2];
                    int dataLength = int.Parse(parts[3]);
                    // البيانات ستأتي في الرسائل التالية
                    conn.ATMData.IsSendingData = true;
                    conn.ATMData.LastDataReceived = DateTime.Now;
                    conn.ATMData.Status = ATMStatus.Online_Active;
                    conn.ATMData.TotalLinesSent++;
    
                    // حفظ البيانات
                    OnDataReceived?.Invoke(atmId, fileName, null);
                    conn.Send(Protocol.DATA_ACK);
                }
                break;
    
                case Protocol.DATA_FILE:
                if (parts.Length >= 5)
                {
                    string fileName = parts[2];
                    conn.ATMData.IsSendingData = true;
                    conn.ATMData.LastDataReceived = DateTime.Now;
                    conn.ATMData.TotalFilesSynced++;
    
                    OnFileReceived?.Invoke(atmId, fileName, null);
                    conn.Send(Protocol.DATA_ACK);
                }
                break;
    
                case Protocol.STATUS_RESPONSE:
                if (parts.Length >= 4)
                {
                    string status = parts[2];
                    string cscStatus = parts.Length > 3 ? parts[3] : "";
                    conn.ATMData.IsCSCConnected = (cscStatus == "CSC_OK");
                    OnStatusReceived?.Invoke(atmId, status);
                }
                break;
    
                case Protocol.CMD_RESULT:
                if (parts.Length >= 4)
                {
                    string cmdId = parts[2];
                    string result = parts[3];
                    OnCommandResult?.Invoke(atmId, cmdId, result);
                }
                break;
            }
            }
    
            private string ReadLine(NetworkStream stream, int timeoutMs)
            {
            byte[] buffer = new byte[4096];
            stream.ReadTimeout = timeoutMs;
            try
            {
                int bytesRead = stream.Read(buffer, 0, buffer.Length);
                if (bytesRead > 0)
                return Encoding.UTF8.GetString(buffer, 0, bytesRead).Trim();
            }
            catch { }
            return null;
            }
    
            #endregion
        }
        public partial class ServerEngine
        {
            private TcpListener _listener;
    
    
            private bool _isProcessing = false;
    
    
            private string _archivePath;
    
    
            public bool IsRunning { get; private set; } = false;
    
    
            public int Port { get; set; } = 8080;
    
    
            public string Host { get; set; } = "localhost";
    
    
            public DateTime StartTime { get; private set; }
    
    
            public ServerEngine(int port, string archivePath)
            {
            Port = port;
            _archivePath = archivePath;
            StartTime = DateTime.Now;
            }
    
    
            private readonly List<ConnectedClient> _clients = new List<ConnectedClient>();
    
    
            private readonly object _lockObject = new object();
    
    
            public void Start()
            {
            try
            {
            _listener = new TcpListener(IPAddress.Any, Port);
            _listener.Start();
            IsRunning = true;
            StartTime = DateTime.Now;
    
            // Start listening for connections
            Task.Run(() => AcceptClients());
    
            OnLog?.Invoke($"[Server] Started on port {Port}");
            }
            catch (Exception ex)
            {
            OnError?.Invoke(ex);
            }
            }
    
    
            public void Stop()
            {
            try
            {
            _isProcessing = false;
            _listener?.Stop();
            IsRunning = false;
    
            // Disconnect all clients
            lock (_lockObject)
            {
            foreach (var client in _clients)
            {
                client.TcpClient?.Close();
            }
            _clients.Clear();
            }
    
            OnLog?.Invoke("[Server] Stopped");
            }
            catch (Exception ex)
            {
            OnError?.Invoke(ex);
            }
            }
    
    
            private async Task AcceptClients()
            {
            _isProcessing = true;
            OnLog?.Invoke("[Server] Listening for connections...");
    
            while (_isProcessing && IsRunning)
            {
            try
            {
            var tcpClient = await _listener.AcceptTcpClientAsync();
            var client = new ConnectedClient
            {
                TcpClient = tcpClient,
                IP = ((IPEndPoint)tcpClient.Client.RemoteEndPoint).Address.ToString(),
                ConnectedAt = DateTime.Now
            };
    
            lock (_lockObject)
            {
                _clients.Add(client);
            }
    
            OnLog?.Invoke($"[Server] Client connected from {client.IP}");
    
            // Start processing this client
            Task.Run(() => ProcessClient(client));
            }
            catch (ObjectDisposedException)
            {
            // Server stopped
            break;
            }
            catch (Exception ex)
            {
            if (_isProcessing)
            {
                OnError?.Invoke(ex);
            }
            }
            }
            }
    
    
            private async void ProcessClient(ConnectedClient client)
            {
            try
            {
            var stream = client.TcpClient.GetStream();
            var buffer = new byte[4096];
            var atmId = "Unknown";
    
            while (IsRunning && client.TcpClient.Connected)
            {
            // Read data from client
            int bytesRead = await stream.ReadAsync(buffer, 0, buffer.Length);
            if (bytesRead == 0)
            {
                // Client disconnected
                break;
            }
    
            var data = Encoding.UTF8.GetString(buffer, 0, bytesRead);
            ProcessClientMessage(client, data, ref atmId);
            }
            }
            catch (Exception ex)
            {
            OnError?.Invoke(ex);
            }
            finally
            {
            // Client disconnected
            HandleClientDisconnection(client, atmId);
            }
            }
    
    
            private void ProcessClientMessage(ConnectedClient client, string data, ref string atmId)
            {
            try
            {
            // Parse the message
            var parts = data.Split('|');
            if (parts.Length > 0)
            {
            switch (parts[0])
            {
                case "EJLIVE_HANDSHAKE":
                if (parts.Length >= 3)
                {
                atmId = parts[1];
                var atmType = parts[2];
                client.ATMId = atmId;
                client.ATMType = atmType;
                OnClientConnected?.Invoke(atmId, atmType, client.IP);
    
                // Send handshake acknowledgment
                SendDataToClient(client, "EJLIVE_ACK");
                }
                break;
    
                case "EJDATA":
                if (parts.Length >= 3)
                {
                var fileName = parts[1];
                var fileData = parts[2];
    
                // Save the journal file
                SaveJournalFile(client.ATMId, fileName, fileData);
                OnJournalReceived?.Invoke(client.ATMId, fileName, fileData.Length);
                }
                break;
    
                case "CMD_RESULT":
                if (parts.Length >= 4)
                {
                var command = parts[1];
                var success = parts[2] == "SUCCESS";
                var result = parts[3];
                OnCommandResult?.Invoke(client.ATMId, command, success, result);
                }
                break;
            }
            }
            }
            catch (Exception ex)
            {
            OnError?.Invoke(ex);
            }
            }
    
    
            private void HandleClientDisconnection(ConnectedClient client, string atmId)
            {
            try
            {
            lock (_lockObject)
            {
            _clients.Remove(client);
            }
    
            if (client.TcpClient != null)
            {
            client.TcpClient.Close();
            }
    
            if (!string.IsNullOrEmpty(atmId) && atmId != "Unknown")
            {
            OnClientDisconnected?.Invoke(atmId);
            }
    
            OnLog?.Invoke($"[Server] Client {atmId} disconnected");
            }
            catch (Exception ex)
            {
            OnError?.Invoke(ex);
            }
            }
    
    
            private void SaveJournalFile(string atmId, string fileName, string fileData)
            {
            try
            {
            var atmPath = Path.Combine(_archivePath, atmId);
            if (!Directory.Exists(atmPath))
            {
            Directory.CreateDirectory(atmPath);
            }
    
            var filePath = Path.Combine(atmPath, fileName);
            File.WriteAllText(filePath, fileData);
            }
            catch (Exception ex)
            {
            OnError?.Invoke(ex);
            }
            }
    
    
            public void SendCommand(string atmId, string command, string[] parameters)
            {
            lock (_lockObject)
            {
            var client = _clients.Find(c => c.ATMId == atmId);
            if (client != null)
            {
            var message = Protocol.BuildMessage(command, parameters);
            SendDataToClient(client, message);
            }
            }
            }
    
    
            public void BroadcastCommand(string command, string[] parameters)
            {
            lock (_lockObject)
            {
            var message = Protocol.BuildMessage(command, parameters);
            foreach (var client in _clients)
            {
            SendDataToClient(client, message);
            }
            }
            }
    
    
            public void DisconnectClient(string atmId)
            {
            lock (_lockObject)
            {
            var client = _clients.Find(c => c.ATMId == atmId);
            if (client != null)
            {
            client.TcpClient?.Close();
            }
            }
            }
    
    
            private void SendDataToClient(ConnectedClient client, string data)
            {
            try
            {
            if (client.TcpClient?.Connected == true)
            {
            var bytes = Encoding.UTF8.GetBytes(data);
            var stream = client.TcpClient.GetStream();
            stream.Write(bytes, 0, bytes.Length);
            }
            }
            catch (Exception ex)
            {
            OnError?.Invoke(ex);
            }
            }
    
    
            public bool SendDataToAll(string data)
            {
            lock (_lockObject)
            {
            try
            {
            foreach (var client in _clients)
            {
                SendDataToClient(client, data);
            }
            return true;
            }
            catch (Exception ex)
            {
            OnError?.Invoke(ex);
            return false;
            }
            }
            }
    
    
            public bool SendData(string data, TcpClient tcpClient)
            {
            try
            {
            if (tcpClient?.Connected == true)
            {
            var bytes = Encoding.UTF8.GetBytes(data);
            var stream = tcpClient.GetStream();
            stream.Write(bytes, 0, bytes.Length);
            return true;
            }
            return false;
            }
            catch (Exception ex)
            {
            OnError?.Invoke(ex);
            return false;
            }
            }
    
    
