            private void ProcessPacket(ReceivedPacket pkt, ConcurrentDictionary<string, FileReceiveState> fileStates)
            {
            var session = pkt.Session;
            var atm     = pkt.ATM;
            var msg     = pkt.Message;
    
            switch (msg.Type)
            {
            case CommunicationProtocol.MsgType.StartFile:
            {
