            public event Action<string, string, string> OnCommandResult;  // (atmId, cmdId, result)
    
    
            public event Action<string> OnLog;
    
    
            public event Action<Exception> OnError;
    
    
            // Variant from: d:\EJLIVE\EJlive_Reference_Projects\CodexMarege_Unified\CodexMaregerestructuredReplitFinalzip\EJLive.Core\Engine\ServerEngine.cs
            public event Action<string, string, string> OnCommandResult;  // (atmId, cmdId, result)
    
    
            // Variant from: d:\EJLIVE\EJlive_Reference_Projects\CodexMaregerestructured\CodexMaregerestructuredReplitFinalzip\EJLive.Core\Engine\ServerEngine.cs
