                    {
                    lock (_connectionsLock)
                    {
                        if (!_connections.ContainsKey(atmId)) return false;
                        var conn = _connections[atmId];
                        string msg = Protocol.BuildMessage(command, parameters);
                        return conn.Send(msg);
