                    /// إيقاف السيرفر
                    /// </summary>
                    public void Stop()
                    {
                        _isRunning = false;
                        try
                        {
                            _listener?.Stop();
                            lock (_connectionsLock)
                            {
                                foreach (var conn in _connections.Values)
                                    conn.Disconnect();
                                _connections.Clear();
                            }
                        }
                        catch { }
                        OnLog?.Invoke("[Server] Stopped");
