                                        var frame = CommunicationProtocol.BuildBroadcast(message, session.SessionKey);
                                        lock (session.SendLock)
                                            session.Stream.Write(frame, 0, frame.Length);
                                    }
                                    catch { }
                                }
                                Log($"★ Broadcast sent to {_sessions.Count} clients: {message}");
                            }
    
