                                    }
    
                                    case CommunicationProtocol.MsgType.CommandResult:
                                    {
                                        var parts   = msg.Text.Split('|');
                                        var cmdId   = parts.Length > 1 ? parts[1] : "";
                                        var success = parts.Length > 2 && parts[2] == "SUCCESS";
                                        var result  = parts.Length > 3 ? parts[3] : "";
