                                                _commandLedger[cmdId] = tracked;
                                            }
    
                                            tracked.Status     = success ? "Executed" : "Failed";
                                            tracked.Result     = result;
                                            tracked.AckedAtUtc = DateTime.UtcNow;
                                            tracked.ExecutedAt = DateTime.UtcNow;
